import {mountToolJobPanel} from './tool-job-panel.mjs';
import {revisionAiSnapshot,applyRevisionAiOutput} from './revision-ai-model.mjs';
import {esc,icon} from './ui.mjs';
export function mountRevisionAi({container,ctx,getDocument,updateDocument,getIndex=()=>0,beforeOpen=()=>{},isCurrent=()=>true}){
 const win=container.ownerDocument.defaultView;let live=true,scope=getDocument()?.aiJobStates?.rewrite?.snapshot?.context?.scope==='all'?'all':'current',panel;const initial=getDocument()?.id,current=()=>live&&container.isConnected&&getDocument()?.id===initial&&isCurrent();
 if(!container.ownerDocument.querySelector('[data-revision-ai-style]')){const link=container.ownerDocument.createElement('link');link.rel='stylesheet';link.href='/workspace/revision-ai.css';link.dataset.revisionAiStyle='';container.ownerDocument.head.append(link);}
 container.innerHTML=`<section class="rev-ai-card"><div class="rev-ai-title"><span>${icon('spark',23)}</span><div><h3>AI 表达优化</h3><p>保留原稿，生成逐段候选；核对并采纳后，才会进入导出稿。</p></div><span class="rev-ai-review-badge">先预览 · 再采纳</span></div><div class="rev-ai-controls"><label>处理范围<select data-rev-ai-scope><option value="current" ${scope==='current'?'selected':''}>当前段落</option><option value="all" ${scope==='all'?'selected':''}>全部原文段落</option></select></label><button class="btn primary" type="button" data-rev-ai-open>生成候选修改 ${icon('arrow',15)}</button></div><p class="rev-ai-note">每次最多 32,000 字符、单段最多 3,500 字符。成功后按确认费用结算；不预测或承诺重复率、AI 检测率。</p><div data-rev-ai-panel hidden></div></section>`;
 const snapshot=()=>revisionAiSnapshot(getDocument(),{scope,index:getIndex()});
 panel=mountToolJobPanel({container:container.querySelector('[data-rev-ai-panel]'),ctx,kind:'revision',operation:'rewrite',getSnapshot:snapshot,isCurrent:current,initialState:getDocument()?.aiJobStates?.rewrite||{},onStateChange:state=>{if(current())updateDocument(doc=>({...doc,aiJobStates:{...doc.aiJobStates,rewrite:state}}),{redraw:false});},onApply:(output,item)=>{const input=snapshot();updateDocument(doc=>{if((doc.appliedAiJobs||[]).includes(item.id))return doc;const next=applyRevisionAiOutput(doc,output,input);return {...next,appliedAiJobs:[...(doc.appliedAiJobs||[]),item.id].slice(-100)};},{label:'AI 候选修改',redraw:true});ctx.notify?.('候选修改已保存，原文未被覆盖。请逐段查看差异并决定是否采纳。');}});
 container.querySelector('[data-rev-ai-scope]').onchange=e=>{scope=e.target.value;panel.inputChanged?.();};container.querySelector('[data-rev-ai-open]').onclick=()=>{try{beforeOpen();void panel.open();}catch(error){ctx.notify?.(error.message||'请先保存当前编辑。');}};
 return {dispose(){live=false;panel.dispose();},getState:()=>({scope}),inputChanged(){beforeOpen();panel.inputChanged?.();}};
}
